INSERT INTO `forum_comments` VALUES ('c-rust-1','post-rust-hashmap',NULL,'user-benq','Map 有额外的哈希和装箱开销。在竞赛中，如果键是小整数，使用 null-prototype 对象或数组通常更快。',NULL,'2026-05-06 15:03:30.496',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-rust-2','post-rust-hashmap','c-rust-1','u-002','有道理。我之前以为 Map 默认最快。我试试 null-prototype 对象。',NULL,'2026-05-06 15:03:30.503',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-rust-3','post-rust-hashmap','c-rust-2','user-petr','注意对象的使用：键的字符串化或混合类型会严重影响性能。保持键类型一致。',NULL,'2026-05-06 15:03:30.508',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-rust-4','post-rust-hashmap','c-rust-3','user-yuki','JS 评测系统会包含对抗性键模式吗？还是测试用例大多是静态的？',NULL,'2026-05-06 15:03:30.516',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-rust-5','post-rust-hashmap','c-rust-4','user-petr','是静态的，但不良的键分布仍有影响。如果键空间密集，用数组。',NULL,'2026-05-06 15:03:30.521',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-rust-6','post-rust-hashmap',NULL,'user-alex','在 JS 中，数组对于密集整数键通常最快。',NULL,'2026-05-06 15:03:30.527',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-seg-1','post-segtree-visual',NULL,'user-jiangly','可视化做得很好。第 3 页有个小笔误：「propogate」应该是「propagate」。',NULL,'2026-05-06 15:03:30.533',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-seg-2','post-segtree-visual','c-seg-1','user-tourist','已修复！感谢指正。🙏',NULL,'2026-05-06 15:03:30.538',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-seg-3','post-segtree-visual',NULL,'user-kevin','这个支持线段树 beats 吗？',NULL,'2026-05-06 15:03:30.545',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-seg-4','post-segtree-visual','c-seg-3','user-tourist','暂不支持。Beats 需要追踪最小值/最大值/次大值，不太容易清晰可视化。',NULL,'2026-05-06 15:03:30.548',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-seg-5','post-segtree-visual','c-seg-3','user-max','可以看看 JiDriver 的博客，有 Segment Tree Beats 的可视化。',NULL,'2026-05-06 15:03:30.552',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-tilt-1','post-contest-tilt',NULL,'u-001','呼吸法：吸气 4 秒，屏息 4 秒，呼气 4 秒。重复 3 次。从生理上强制降低心率。',NULL,'2026-05-06 15:03:30.555',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-tilt-2','post-contest-tilt','c-tilt-1','user-david','下次模拟赛试试。我通常就是盯着屏幕过度换气 lol。',NULL,'2026-05-06 15:03:30.559',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-tilt-3','post-contest-tilt','c-tilt-2','user-lily','另外，站起来。物理上改变姿势可以重置「管状视野」。',NULL,'2026-05-06 15:03:30.563',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-tilt-4','post-contest-tilt',NULL,'user-scott','我通常直接退出去看 League。（别学我）',NULL,'2026-05-06 15:03:30.566',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-tilt-5','post-contest-tilt','c-tilt-4','user-tom','笑死，上次 CF 我就是这样。',NULL,'2026-05-06 15:03:30.569',NULL,0,0,0,NULL,NULL,0,NULL,NULL),('c-tilt-6','post-contest-tilt',NULL,'user-sara','我喝冷水。温度刺激能唤醒前额叶皮层。',NULL,'2026-05-06 15:03:30.573',NULL,0,0,1,'1111','2026-05-16 18:42:32.394',0,NULL,NULL),('c-tilt-7','post-contest-tilt','c-tilt-6','user-emma','科学！',NULL,'2026-05-06 15:03:30.576',NULL,0,0,1,'1111','2026-05-16 18:42:16.552',0,NULL,NULL);
