INSERT INTO `forum_community_rules` VALUES ('rule-career-1','community-career','保持专业','所有职业讨论中保持专业和礼貌的交流。',1,'2026-05-06 15:03:30.731'),('rule-comp-1','community-compensation','诚实准确','分享准确的薪酬数据，帮助社区成员做出更好的决策。',1,'2026-05-06 15:03:30.735'),('rule-interview-1','community-interview','尊重他人','每个人的面试经历都不同。请保持支持和建设性的态度。',1,'2026-05-06 15:03:30.738'),('rule-interview-2','community-interview','保护机密','请勿分享受保密协议（NDA）约束的信息或面试题目。',2,'2026-05-06 15:03:30.744'),('rule-tech-1','community-technology','展示你的尝试','提出技术问题时，请附上代码片段或你的思路。',1,'2026-05-06 15:03:30.747'),('rule-tech-2','community-technology','建设性反馈','保持反馈可操作和尊重。',2,'2026-05-06 15:03:30.751'),('rule-tech-3','community-technology','使用剧透标签','对正在进行中的比赛，请用剧透标签标记题解内容。',3,'2026-05-06 15:03:30.755');
