INSERT INTO `forum_posts` VALUES ('post-contest-tilt','community-technology','user-david',NULL,'「30分钟撞墙」：比赛中如何重置心态？','discussion',NULL,'[\"mindset\", \"psychology\", \"strategy\"]','昨天 Q2 卡了 40 分钟 debug 一个 off-by-one，之后 Q3/Q4 完全无法集中，脑子像灌了浆糊。\n\n大家有没有什么物理或心理上的硬重置方法？听说过有人做俯卧撑或者泼冷水。',NULL,NULL,'neutral',0,5120,1,0,'2026-05-06 15:03:30.476','{\"saves\": 0, \"views\": 0, \"awards\": 0, \"shares\": 0, \"comments\": 7}',15,0,NULL,NULL,0,NULL,NULL),('post-rust-hashmap','community-technology','u-002',NULL,'为什么 JavaScript 竞赛中 Map 比普通对象慢？','question',NULL,'[\"typescript\", \"performance\", \"hashing\"]','最近刷 AtCoder 性能题，发现 Map 和普通对象之间有巨大的性能差距。',NULL,NULL,'neutral',0,4200,0,0,'2026-05-06 15:03:30.484','{\"saves\": 0, \"views\": 0, \"awards\": 0, \"shares\": 0, \"comments\": 6}',8,0,NULL,NULL,0,NULL,NULL),('post-segtree-visual','community-technology','user-tourist',NULL,'线段树可视化指南（懒标记传播）','showcase',NULL,'[\"tutorial\", \"segment-tree\", \"visualization\"]','写了一个交互式博客，可视化懒标记在查询时如何向下传播。\n\n[可视化链接](https://example.com/segtree-vis)\n\n核心洞察：「懒标记就是待执行的操作」。\n大部分 bug 来自：\n1. 读取子节点前没有 pushdown。\n2. 子节点返回后没有更新当前节点。\n\n觉得有帮助的话欢迎反馈！','[{\"src\": \"https://images.unsplash.com/photo-1509228468518-180dd4864904?auto=format&fit=crop&w=1200&q=80\", \"kind\": \"image\", \"type\": \"image\", \"ratio\": 1.777777777777778}]',NULL,'neutral',1,8900,0,0,'2026-05-06 15:03:30.489','{\"saves\": 0, \"views\": 0, \"awards\": 0, \"shares\": 0, \"comments\": 5}',1,0,NULL,NULL,0,NULL,NULL);
/*!40000 ALTER TABLE `forum_posts` ENABLE KEYS */;
