INSERT INTO `notifications` VALUES ('notif-cmt-001','user-tourist','COMMENT','COMMUNICATION','stack_unwind 评论了你的帖子「Segment Tree Beats 可视化指南」','\"Lazy propagation 的可视化太清晰了，请问这个是用 D3.js 画的吗？想参考一下你的渲染逻辑。\"','/forum/post-segtree-visual','{\"entity_id\": \"post-segtree-visual\", \"entity_type\": \"forum_post\", \"commenter_id\": \"u-002\", \"commenter_username\": \"stack_unwind\"}',NULL,0,NULL,'2026-05-06 15:03:37.091','2026-05-06 15:03:37.091'),('notif-cmt-002','user-alex','COMMENT','COMMUNICATION','chen_master 评论了你的题解「Two Sum 暴力解法」','\"暴力解法确实是最直观的入门方式，建议加一句时间复杂度 O(n²) 的提示，方便新手理解优化方向。\"','/solutions/sol-002','{\"entity_id\": \"sol-002\", \"problem_id\": 1, \"entity_type\": \"solution\", \"commenter_id\": \"user-chen\", \"problem_slug\": \"two-sum\", \"commenter_username\": \"chen_master\"}',NULL,1,'2026-05-06 15:03:37.096','2026-05-06 15:03:37.096','2026-05-06 15:03:37.096'),('notif-cmt-003','user-david','COMMENT','COMMUNICATION','jiangly 评论了你的帖子「比赛心态调整」','\"深有同感。我之前 CF 连掉两场 Div1 之后也是靠暂停一周恢复的。分享一个方法：每场赛前写 3 个具体目标，不关注排名。\"','/forum/post-contest-tilt','{\"entity_id\": \"post-contest-tilt\", \"entity_type\": \"forum_post\", \"commenter_id\": \"user-jiangly\", \"commenter_username\": \"jiangly\"}',NULL,0,NULL,'2026-05-06 15:03:37.100','2026-05-06 15:03:37.100'),('notif-cmt-004','user-max','COMMENT','COMMUNICATION','sara_dev 评论了你的题解「合并区间 Sort-and-Sweep」','\"申诉通过了！恭喜。边界条件确实处理得很干净，我之前的报告是误解了 merge 逻辑。\"','/solutions/sol-006','{\"entity_id\": \"sol-006\", \"problem_id\": 3, \"entity_type\": \"solution\", \"commenter_id\": \"user-sara\", \"problem_slug\": \"merge-intervals\", \"commenter_username\": \"sara_dev\"}',NULL,0,NULL,'2026-05-06 15:03:37.103','2026-05-06 15:03:37.103'),('notif-con-001','user-tourist','CONTEST','SYSTEM','周赛 477 即将开始','距离 UltiCode 周赛 477 开赛还有 1 小时。本次共 4 道题，难度递增。准备好你的编程环境！','/contests/contest-weekly-477','{\"entity_id\": \"contest-weekly-477\", \"start_time\": \"2026-04-06T10:00:00\", \"entity_type\": \"contest\", \"contest_name\": \"UltiCode Weekly Contest 477\", \"problem_count\": 4, \"duration_minutes\": 90}',NULL,0,NULL,'2026-05-06 15:03:37.179','2026-05-06 15:03:37.179'),('notif-con-002','user-benq','CONTEST','SYSTEM','恭喜获得 UltiCode 周赛 476 第 1 名','你以 4 题全通、用时 78 分钟的成绩夺得周赛 476 冠军。Rating +42。','/contests/contest-weekly-476/ranking','{\"rank\": 1, \"solved\": 4, \"entity_id\": \"contest-weekly-476\", \"entity_type\": \"contest\", \"contest_name\": \"UltiCode Weekly Contest 476\", \"rating_change\": 42, \"total_time_min\": 78}',NULL,1,'2026-05-06 15:03:37.182','2026-05-06 15:03:37.182','2026-05-06 15:03:37.182'),('notif-con-003','user-jiangly','CONTEST','SYSTEM','双周赛 170 排名已更新','你在 UltiCode 双周赛 170 中获得第 5 名（3/4 题，用时 65 分钟）。Rating +18。','/contests/contest-biweekly-170/ranking','{\"rank\": 5, \"solved\": 3, \"entity_id\": \"contest-biweekly-170\", \"entity_type\": \"contest\", \"contest_name\": \"UltiCode Biweekly Contest 170\", \"rating_change\": 18, \"total_problems\": 4, \"total_time_min\": 65}',NULL,1,'2026-05-06 15:03:37.185','2026-05-06 15:03:37.185','2026-05-06 15:03:37.185'),('notif-con-004','user-ecnerwala','CONTEST','SYSTEM','周赛 477 已结束，查看排行榜','UltiCode 周赛 477 已结束，你获得第 3 名。查看完整排行榜和题解讨论。','/contests/contest-weekly-477/ranking','{\"rank\": 3, \"solved\": 4, \"entity_id\": \"contest-weekly-477\", \"entity_type\": \"contest\", \"contest_name\": \"UltiCode Weekly Contest 477\", \"rating_change\": 28}',NULL,0,NULL,'2026-05-06 15:03:37.189','2026-05-06 15:03:37.189'),('notif-fol-001','user-tourist','FOLLOW','COMMUNICATION','Benq 关注了你','Benq 开始关注你的动态，你可以在个人主页查看互关状态。','/users/Benq','{\"follower_id\": \"user-benq\", \"total_followers\": 1523, \"follower_username\": \"Benq\"}',NULL,0,NULL,'2026-05-06 15:03:37.147','2026-05-06 15:03:37.147'),('notif-fol-002','user-benq','FOLLOW','COMMUNICATION','ecnerwala 关注了你','ecnerwala 开始关注你的动态。','/users/ecnerwala','{\"follower_id\": \"user-ecnerwala\", \"total_followers\": 2341, \"follower_username\": \"ecnerwala\"}',NULL,1,'2026-05-06 15:03:37.151','2026-05-06 15:03:37.151','2026-05-06 15:03:37.151'),('notif-fol-003','user-jiangly','FOLLOW','COMMUNICATION','Petr 关注了你','Petr 开始关注你的动态。','/users/Petr','{\"follower_id\": \"user-petr\", \"total_followers\": 1897, \"follower_username\": \"Petr\"}',NULL,0,NULL,'2026-05-06 15:03:37.154','2026-05-06 15:03:37.154'),('notif-ment-001','user-benq','MENTION','COMMUNICATION','tourist 在帖子中提到了你','\"@Benq 之前你在 CF blog 里分析的 SwissTable 实现我也参考了，特别是 SIMD probing 那部分。\"','/forum/post-rust-hashmap','{\"entity_id\": \"post-rust-hashmap\", \"entity_type\": \"forum_post\", \"mentioner_id\": \"user-tourist\", \"mentioner_username\": \"tourist\"}',NULL,0,NULL,'2026-05-06 15:03:37.119','2026-05-06 15:03:37.119'),('notif-ment-002','user-ecnerwala','MENTION','COMMUNICATION','jiangly 在题解中提到了你','\"@ecnerwala 你之前 AtCoder ABC 上的 one-pass hash 解法非常优雅，我把思路整理进来了。\"','/solutions/sol-001','{\"entity_id\": \"sol-001\", \"problem_id\": 1, \"entity_type\": \"solution\", \"mentioner_id\": \"user-jiangly\", \"problem_slug\": \"two-sum\", \"mentioner_username\": \"jiangly\"}',NULL,1,'2026-05-06 15:03:37.123','2026-05-06 15:03:37.123','2026-05-06 15:03:37.123'),('notif-ment-003','user-jiangly','MENTION','COMMUNICATION','ecnerwala 在评论中提到了你','\"@jiangly 这个 lazy tag 的处理方式和你在 Yandex.Algorithm 2023 决赛用的那个 segment tree beats 是不是同一个思路？\"','/forum/post-segtree-visual','{\"post_id\": \"post-segtree-visual\", \"entity_id\": \"c-seg-4\", \"entity_type\": \"forum_comment\", \"mentioner_id\": \"user-ecnerwala\", \"mentioner_username\": \"ecnerwala\"}',NULL,0,NULL,'2026-05-06 15:03:37.127','2026-05-06 15:03:37.127'),('notif-reply-001','user-kevin','REPLY','COMMUNICATION','Benq 回复了你在「Rust HashMap 性能深度对比」下的评论','\"V8 的 hidden class 机制确实让 object key 的类型问题没那么严重了，但在 HashMap 场景下 Rust 的 typed key 还是更安全。\"','/forum/post-rust-hashmap','{\"post_id\": \"post-rust-hashmap\", \"entity_id\": \"c-rust-3\", \"replier_id\": \"user-benq\", \"entity_type\": \"forum_comment\", \"replier_username\": \"Benq\"}',NULL,1,'2026-05-06 15:03:37.108','2026-05-06 15:03:37.108','2026-05-06 15:03:37.108'),('notif-reply-002','user-sara','REPLY','COMMUNICATION','david_algo 回复了你的评论','\"冷水洗脸确实有生理学依据——mammalian dive reflex 会激活副交感神经。不过比赛时更推荐 4-7-8 呼吸法，不需要离开键盘。\"','/forum/post-contest-tilt','{\"post_id\": \"post-contest-tilt\", \"entity_id\": \"c-tilt-2\", \"replier_id\": \"user-david\", \"entity_type\": \"forum_comment\", \"replier_username\": \"david_algo\"}',NULL,0,NULL,'2026-05-06 15:03:37.112','2026-05-06 15:03:37.112'),('notif-reply-003','user-lily','REPLY','COMMUNICATION','tom_quick 回复了你对题解的追问','\"这道题确实可以不处理 duplicates。题目保证了每个元素只有唯一解，所以 map 里不会出现覆盖的情况。\"','/solutions/sol-001','{\"entity_id\": \"comment-003\", \"replier_id\": \"user-tom\", \"entity_type\": \"solution_comment\", \"solution_id\": \"sol-001\", \"replier_username\": \"tom_quick\"}',NULL,1,'2026-05-06 15:03:37.115','2026-05-06 15:03:37.115','2026-05-06 15:03:37.115'),('notif-sub-001','user-alex','SUBMISSION','SYSTEM','提交通过：Two Sum','Runtime: 2ms | Memory: 42.1MB | 击败 89.7% 的用户','/problems/two-sum/submissions/latest','{\"status\": \"Accepted\", \"language\": \"Java\", \"memory_mb\": 42.1, \"problem_id\": 1, \"runtime_ms\": 2, \"entity_type\": \"submission\", \"beat_percent\": 89.7, \"problem_slug\": \"two-sum\"}',NULL,1,'2026-05-06 15:03:37.158','2026-05-06 15:03:37.158','2026-05-06 15:03:37.158'),('notif-sub-002','user-max','SUBMISSION','SYSTEM','提交失败：Median of Two Sorted Arrays — Time Limit Exceeded','Test Case #26 超时。提示：考虑 O(log(min(m,n))) 的二分解法。','/problems/median-of-two-sorted-arrays/submissions/latest','{\"status\": \"Time Limit Exceeded\", \"language\": \"Python\", \"problem_id\": 4, \"entity_type\": \"submission\", \"failed_test\": 26, \"problem_slug\": \"median-of-two-sorted-arrays\"}',NULL,0,NULL,'2026-05-06 15:03:37.162','2026-05-06 15:03:37.162'),('notif-sub-003','user-sara','SUBMISSION','SYSTEM','提交通过：Number of Islands','Runtime: 4ms | Memory: 38.5MB | 击败 92.3% 的用户 — BFS 解法表现优异','/problems/number-of-islands/submissions/latest','{\"status\": \"Accepted\", \"language\": \"Java\", \"memory_mb\": 38.5, \"problem_id\": 5, \"runtime_ms\": 4, \"entity_type\": \"submission\", \"beat_percent\": 92.3, \"problem_slug\": \"number-of-islands\"}',NULL,1,'2026-05-06 15:03:37.166','2026-05-06 15:03:37.166','2026-05-06 15:03:37.166'),('notif-sub-004','user-emma','SUBMISSION','SYSTEM','提交失败：Merge Intervals — Wrong Answer on Test #47','预期输出 [[1,6],[8,10],[15,18]]，实际输出 [[1,5],[8,10],[15,18]]。提示：检查区间合并时的右边界取值。','/problems/merge-intervals/submissions/latest','{\"actual\": \"[[1,5],[8,10],[15,18]]\", \"status\": \"Wrong Answer\", \"expected\": \"[[1,6],[8,10],[15,18]]\", \"language\": \"C++\", \"problem_id\": 3, \"entity_type\": \"submission\", \"failed_test\": 47, \"problem_slug\": \"merge-intervals\"}',NULL,0,NULL,'2026-05-06 15:03:37.170','2026-05-06 15:03:37.170'),('notif-sub-005','user-kevin','SUBMISSION','SYSTEM','提交通过：Longest Substring Without Repeating Characters','Runtime: 4ms | Memory: 40.2MB | 击败 85.1% 的用户','/problems/longest-substring-without-repeating-characters/submissions/latest','{\"status\": \"Accepted\", \"language\": \"Go\", \"memory_mb\": 40.2, \"problem_id\": 2, \"runtime_ms\": 4, \"entity_type\": \"submission\", \"beat_percent\": 85.1, \"problem_slug\": \"longest-substring-without-repeating-characters\"}',NULL,1,'2026-05-06 15:03:37.175','2026-05-06 15:03:37.175','2026-05-06 15:03:37.175'),('notif-sys-001','user-alex','SYSTEM','SECURITY','密码修改成功','你的 UltiCode 账户密码已于 2026-04-02 09:30 成功修改。如果这不是你本人操作，请立即联系管理员。','/settings/security','{\"ip\": \"203.0.113.42\", \"action\": \"password_changed\", \"timestamp\": \"2026-04-02T09:30:00\", \"user_agent\": \"Chrome 124 / macOS\"}',NULL,1,'2026-05-06 15:03:37.193','2026-05-06 15:03:37.193','2026-05-06 15:03:37.193'),('notif-sys-002','user-max','SYSTEM','SECURITY','检测到新设备登录','你的账户在新设备上登录。设备：Windows 11 / Firefox 125，IP：198.51.100.17，位置：上海。如果这不是你本人操作，请立即修改密码。','/settings/security','{\"ip\": \"198.51.100.17\", \"action\": \"new_device_login\", \"device\": \"Windows 11 / Firefox 125\", \"location\": \"Shanghai\", \"timestamp\": \"2026-04-04T18:20:00\"}',NULL,0,NULL,'2026-05-06 15:03:37.197','2026-05-06 15:03:37.197'),('notif-sys-003','user-alex','SYSTEM','SYSTEM','你的题解已被管理员隐藏','你的题解「Two Sum 暴力解法」因缺少时间复杂度警告被管理员隐藏。请在添加 O(n²) 性能限制说明后提交申诉恢复。','/solutions/sol-002','{\"action\": \"content_hidden\", \"reason\": \"ç¼ºå°‘æ—¶é—´å¤æ‚åº¦è­¦å‘Šï¼Œå¯èƒ½è¯¯å¯¼åˆå­¦è€…\", \"entity_id\": \"sol-002\", \"entity_type\": \"solution\", \"moderation_queue_id\": \"mq-003\"}',NULL,1,'2026-05-06 15:03:37.200','2026-05-06 15:03:37.200','2026-05-06 15:03:37.200'),('notif-up-001','user-tourist','UPVOTE','COMMUNICATION','你的题解「Two Sum JS HashMap 解法」获得了 50 个赞','你的 Two Sum 题解持续受到社区好评，目前累计 50 个赞。','/solutions/sol-004','{\"entity_id\": \"sol-004\", \"problem_id\": 1, \"entity_type\": \"solution\", \"problem_slug\": \"two-sum\", \"upvote_count\": 50}',NULL,1,'2026-05-06 15:03:37.131','2026-05-06 15:03:37.131','2026-05-06 15:03:37.131'),('notif-up-002','user-david','UPVOTE','COMMUNICATION','你的帖子「比赛心态调整」获得了 128 个赞','这个话题引发了广泛共鸣，你的分享帮助了很多 Competitive Programmer。','/forum/post-contest-tilt','{\"entity_id\": \"post-contest-tilt\", \"entity_type\": \"forum_post\", \"upvote_count\": 128}',NULL,1,'2026-05-06 15:03:37.135','2026-05-06 15:03:37.135','2026-05-06 15:03:37.135'),('notif-up-003','user-benq','UPVOTE','COMMUNICATION','你的题解「Two Sum O(n) HashMap 解法」获得了 200 个赞','恭喜！你的题解成为 Two Sum 题目下最受欢迎的解法之一。','/solutions/sol-001','{\"entity_id\": \"sol-001\", \"problem_id\": 1, \"entity_type\": \"solution\", \"problem_slug\": \"two-sum\", \"upvote_count\": 200}',NULL,0,NULL,'2026-05-06 15:03:37.140','2026-05-06 15:03:37.140'),('notif-up-004','user-chen','UPVOTE','COMMUNICATION','你的帖子「Rust HashMap 性能深度对比」获得了 85 个赞','性能对比数据受到社区认可，很多用户表示对选型很有帮助。','/forum/post-rust-hashmap','{\"entity_id\": \"post-rust-hashmap\", \"entity_type\": \"forum_post\", \"upvote_count\": 85}',NULL,1,'2026-05-06 15:03:37.143','2026-05-06 15:03:37.143','2026-05-06 15:03:37.143');
