INSERT INTO `solution_comments` VALUES ('comment-001','sol-001',NULL,'user-max','讲解很棒！帮我更好地理解了哈希表。','2026-05-06 15:03:35.703','2026-05-06 15:03:35.703',0,NULL,NULL,0,NULL,NULL),('comment-002','sol-001','comment-001','user-yuki','谢谢！很高兴对你有帮助 😊','2026-05-06 15:03:35.707','2026-05-06 15:03:35.707',0,NULL,NULL,0,NULL,NULL),('comment-003','sol-001',NULL,'user-sara','如果数组中有重复数字怎么办？','2026-05-06 15:03:35.711','2026-05-06 15:03:35.711',0,NULL,NULL,0,NULL,NULL),('comment-004','sol-001','comment-003','user-yuki','好问题！哈希表会覆盖之前的索引，但这没问题，因为我们只需要找到一对有效的解。','2026-05-06 15:03:35.715','2026-05-06 15:03:35.715',0,NULL,NULL,0,NULL,NULL),('comment-005','sol-002',NULL,'user-lily','对初学者来说是个很好的入门起点！','2026-05-06 15:03:35.718','2026-05-06 15:03:35.718',0,NULL,NULL,0,NULL,NULL),('comment-006','sol-003',NULL,'user-david','很喜欢 TypeScript Map 的解法，非常简洁！','2026-05-06 15:03:35.721','2026-05-06 15:03:35.721',0,NULL,NULL,0,NULL,NULL),('comment-007','sol-005',NULL,'user-tom','左指针移动方式的讲解很到位。','2026-05-06 15:03:35.725','2026-05-06 15:03:35.725',0,NULL,NULL,0,NULL,NULL),('comment-008','sol-006',NULL,'user-lily','先排序这个思路被低估了。','2026-05-06 15:03:35.730','2026-05-06 15:03:35.730',0,NULL,NULL,0,NULL,NULL),('comment-009','sol-007',NULL,'user-scott','二分查找的证明思路很有用，谢谢！','2026-05-06 15:03:35.734','2026-05-06 15:03:35.734',0,NULL,NULL,0,NULL,NULL),('comment-010','sol-008',NULL,'user-emma','基于栈的 DFS 避免了递归栈溢出。好技巧。','2026-05-06 15:03:35.737','2026-05-06 15:03:35.737',0,NULL,NULL,0,NULL,NULL);
