user-tourist','javascript','/**\n * @param {number[]} nums\n * @param {number} target\n * @return {number[]}\n */\nvar twoSum = function(nums, target) {\n    const map = new Map();\n    for (let i = 0; i < nums.length; i++) {\n        const complement = target - nums[i];\n        if (map.has(complement)) return [map.get(complement), i];\n        map.set(nums[i], i);\n    }\n    return [];\n};','AC',52,42.1,NULL,'2026-05-06 15:03:20.653',95.2,88.5,NULL,NULL,NULL,0),('sub-002',2,'user-tourist','javascript','/**\n * @param {string} s\n * @return {number}\n */\nvar lengthOfLongestSubstring = function(s) {\n    const set = new Set();\n    let left = 0, maxLen = 0;\n    for (let right = 0; right < s.length; right++) {\n        while (set.has(s[right])) set.delete(s[left++]);\n        set.add(s[right]);\n        maxLen = Math.max(maxLen, right - left + 1);\n    }\n    return maxLen;\n};','AC',68,41.3,NULL,'2026-05-06 15:03:20.658',97.8,85.2,NULL,NULL,NULL,0),('sub-003',3,'user-tourist','javascript','/**\n * @param {number[][]} intervals\n * @return {number[][]}\n */\nvar merge = function(intervals) {\n    intervals.sort((a, b) => a[0] - b[0]);\n    const result = [intervals[0]];\n    for (let i = 1; i < intervals.length; i++) {\n        const last = result[result.length - 1];\n        if (intervals[i][0] <= last[1]) last[1] = Math.max(last[1], intervals[i][1]);\n        else result.push(intervals[i]);\n    }\n    return result;\n};','AC',72,43.8,NULL,'2026-05-06 15:03:20.661',93.1,82.4,NULL,NULL,NULL,0),('sub-004',5,'user-tourist','javascript','/**\n * @param {character[][]} grid\n * @return {number}\n */\nvar numIslands = function(grid) {\n    const m = grid.length, n = grid[0].length;\n    let count = 0;\n    const dfs = (i, j) => {\n        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] !== \'1\') return;\n        grid[i][j] = \'0\';\n        dfs(i+1,j); dfs(i-1,j); dfs(i,j+1); dfs(i,j-1);\n    };\n    for (let i = 0; i < m; i++)\n        for (let j = 0; j < n; j++)\n            if (grid[i][j] === \'1\') { dfs(i,j); count++; }\n    return count;\n};','AC',88,45.2,NULL,'2026-05-06 15:03:20.665',91.5,79.8,NULL,NULL,NULL,0),('sub-005',1,'user-jiangly','typescript','function twoSum(nums: number[], target: number): number[] {\n    const map = new Map<number, number>();\n    for (let i = 0; i < nums.length; i++) {\n        const c = target - nums[i];\n        if (map.has(c)) return [map.get(c)!, i];\n        map.set(nums[i], i);\n    }\n    return [];\n}','AC',48,41.8,NULL,'2026-05-06 15:03:20.671',96.5,87.2,NULL,NULL,NULL,0),('sub-006',2,'user-jiangly','typescript','function lengthOfLongestSubstring(s: string): number {\n    const set = new Set<string>();\n    let left = 0, max = 0;\n    for (let right = 0; right < s.length; right++) {\n        while (set.has(s[right])) set.delete(s[left++]);\n        set.add(s[right]);\n        max = Math.max(max, right - left + 1);\n    }\n    return max;\n}','AC',62,41,NULL,'2026-05-06 15:03:20.675',98.1,86.5,NULL,NULL,NULL,0),('sub-007',3,'user-jiangly','typescript','function merge(intervals: number[][]): number[][] {\n    intervals.sort((a, b) => a[0] - b[0]);\n    const res: number[][] = [intervals[0]];\n    for (let i = 1; i < intervals.length; i++) {\n        const last = res[res.length - 1];\n        if (intervals[i][0] <= last[1]) last[1] = Math.max(last[1], intervals[i][1]);\n        else res.push(intervals[i]);\n    }\n    return res;\n}','AC',65,42.5,NULL,'2026-05-06 15:03:20.689',94.8,83.1,NULL,NULL,NULL,0),('sub-008',5,'user-jiangly','typescript','function numIslands(grid: string[][]): number {\n    const m = grid.length, n = grid[0].length;\n    let count = 0;\n    const dfs = (i: number, j: number) => {\n        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] !== \'1\') return;\n        grid[i][j] = \'0\';\n        dfs(i+1,j); dfs(i-1,j); dfs(i,j+1); dfs(i,j-1);\n    };\n    for (let i = 0; i < m; i++)\n        for (let j = 0; j < n; j++)\n            if (grid[i][j] === \'1\