== 1) return maxLeft;\n            const minRight = i === m ? nums2[j] : j === n ? nums1[i] : Math.min(nums1[i], nums2[j]);\n            return (maxLeft + minRight) / 2;\n        }\n    }\n    return 0;\n};','AC',95,42.5,NULL,'2026-05-06 15:03:20.781',88.5,84.5,NULL,NULL,NULL,0),('sub-032',4,'user-tourist','javascript','var findMedianSortedArrays = function(nums1, nums2) {\n    if (nums1.length > nums2.length) [nums1, nums2] = [nums2, nums1];\n    const m = nums1.length, n = nums2.length;\n    let lo = 0, hi = m;\n    while (lo <= hi) {\n        const i = (lo + hi) >> 1;\n        const j = ((m + n + 1) >> 1) - i;\n        if (i > 0 && nums1[i-1] > nums2[j]) hi = i - 1;\n        else if (i < m && nums2[j-1] > nums1[i]) lo = i + 1;\n        else {\n            const maxL = !i ? nums2[j-1] : !j ? nums1[i-1] : Math.max(nums1[i-1], nums2[j-1]);\n            if ((m+n) & 1) return maxL;\n            const minR = i===m ? nums2[j] : j===n ? nums1[i] : Math.min(nums1[i], nums2[j]);\n            return (maxL + minR) / 2;\n        }\n    }\n};','AC',88,42,NULL,'2026-05-06 15:03:20.786',90,85,NULL,NULL,NULL,0),('sub-033',4,'user-jiangly','typescript','function findMedianSortedArrays(nums1: number[], nums2: number[]): number {\n    if (nums1.length > nums2.length) [nums1, nums2] = [nums2, nums1];\n    const m = nums1.length, n = nums2.length;\n    let lo = 0, hi = m;\n    while (lo <= hi) {\n        const i = (lo + hi) >> 1, j = ((m + n + 1) >> 1) - i;\n        if (i > 0 && nums1[i-1] > nums2[j]) hi = i - 1;\n        else if (i < m && nums2[j-1] > nums1[i]) lo = i + 1;\n        else {\n            const maxL = !i ? nums2[j-1] : !j ? nums1[i-1] : Math.max(nums1[i-1], nums2[j-1]);\n            if ((m+n) & 1) return maxL;\n            const minR = i===m ? nums2[j] : j===n ? nums1[i] : Math.min(nums1[i], nums2[j]);\n            return (maxL + minR) / 2;\n        }\n    }\n    return 0;\n}','AC',92,42.2,NULL,'2026-05-06 15:03:20.789',89.5,84.8,NULL,NULL,NULL,0),('sub-034',4,'user-benq','typescript','function findMedianSortedArrays(nums1: number[], nums2: number[]): number {\n    if (nums1.length > nums2.length) [nums1, nums2] = [nums2, nums1];\n    const m = nums1.length, n = nums2.length;\n    let lo = 0, hi = m;\n    while (lo <= hi) {\n        const i = (lo + hi) >> 1, j = ((m + n + 1) >> 1) - i;\n        if (i > 0 && nums1[i-1] > nums2[j]) hi = i - 1;\n        else if (i < m && nums2[j-1] > nums1[i]) lo = i + 1;\n        else {\n            const maxL = !i ? nums2[j-1] : !j ? nums1[i-1] : Math.max(nums1[i-1], nums2[j-1]);\n            if ((m+n) & 1) return maxL;\n            const minR = i===m ? nums2[j] : j===n ? nums1[i] : Math.min(nums1[i], nums2[j]);\n            return (maxL + minR) / 2;\n        }\n    }\n    return 0;\n}','AC',98,42.8,NULL,'2026-05-06 15:03:20.793',87,83.5,NULL,NULL,NULL,0),('sub-035',5,'user-chen','typescript','function numIslands(grid: string[][]): number {\n    const m = grid.length, n = grid[0].length;\n    let count = 0;\n    const dfs = (i: number, j: number) => {\n        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] !== \'1\') return;\n        grid[i][j] = \'0\';\n        dfs(i+1,j); dfs(i-1,j); dfs(i,j+1); dfs(i,j-1);\n    };\n    for (let i = 0; i < m; i++)\n        for (let j = 0; j < n; j++)\n            if (grid[i][j] === \'1\') { dfs(i,j); count++; }\n    return count;\n}','AC',85,44.2,NULL,'2026-05-06 15:03:20.801',92,80,NULL,NULL,NULL,0),('sub-036',5,'user-petr','javascript','var numIslands = function(grid) {\n    const m = grid.length, n = grid[0].length;\n    let count = 0;\n    const bfs = (si, sj) => {\n        const q = [[si, sj]];\n        grid[si][sj] = \'0\';\n        while (q.length) {\n            const [i, j] = q.shift();\n            for (const [di, dj] of [[1,0],[-1,0],[0,1],[0,-1]]) {\n                const ni = i + di, nj = j + dj;\n                if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] === \'1\') {\n                    grid[ni][nj] = \'0\';\n                  