INSERT INTO `system_announcements` VALUES ('ann-001','UltiCode v2.0 全新升级','我们很高兴地宣布 UltiCode v2.0 正式发布！本次更新包括：\n\n1. 全新的代码编辑器，支持 15+ 编程语言\n2. 实时协作解题功能（Beta）\n3. 重新设计的比赛系统和排行榜\n4. 改进的题解和讨论区体验\n5. 全新的深色模式\n\n感谢社区每一位成员的反馈和建议，让我们一起把 UltiCode 变得更好！','SYSTEM','u-admin-001','2026-05-06 15:03:37.213','2026-05-06 15:03:37.213'),('ann-002','周赛 477 题目预告','UltiCode 周赛 477 将于本周日 10:00 开赛，共 4 道题：\n\n- 第 1 题：数组 / 模拟（Easy）\n- 第 2 题：贪心 / 排序（Medium）\n- 第 3 题：动态规划（Medium）\n- 第 4 题：图论 / 树形 DP（Hard）\n\n比赛时长 90 分钟，建议提前准备好编程环境。','CONTEST','u-admin-001','2026-05-06 15:03:37.217','2026-05-06 15:03:37.217'),('ann-003','安全更新：密码策略变更','为了提升账户安全性，我们将于 2026-04-10 起实施新的密码策略：\n\n1. 密码最低长度从 8 位提升至 10 位\n2. 必须包含大小写字母、数字和特殊字符\n3. 不允许使用近 5 次使用过的密码\n4. 连续登录失败 5 次将锁定账户 30 分钟\n\n请在生效日期前更新你的密码。如有疑问，请联系 security@ulticode.com。','SYSTEM','u-admin-001','2026-05-06 15:03:37.221','2026-05-06 15:03:37.221'),('ann-004','新增 Rust 语言支持','UltiCode 现已全面支持 Rust 编程语言！\n\n- 支持 Rust 2021 edition\n- 内置常用 crate：serde, itertools, regex\n- 新增 10 道 Rust 专属练习题\n- Rust 题解区已开放\n\n感谢社区中 Rust 爱好者的长期呼吁和贡献。','SYSTEM','u-admin-001','2026-05-06 15:03:37.224','2026-05-06 15:03:37.224'),('ann-005','UltiCode 社区规范更新','我们更新了社区行为准则，主要变更如下：\n\n1. 新增「题解质量标准」章节，明确题解应包含思路说明和复杂度分析\n2. 完善举报和申诉流程，新增管理员响应时间承诺（48 小时内）\n3. 强化讨论区礼仪规范，禁止人身攻击和无意义灌水\n4. 新增 AI 辅助生成内容的标注要求\n\n完整规范请查看：/community/guidelines\n\n更新将于 2026-04-15 生效。','SYSTEM','u-admin-001','2026-05-06 15:03:37.228','2026-05-06 15:03:37.228');
/*!40000 ALTER TABLE `system_announcements` ENABLE KEYS */;
